static inline int m3_w64_r50_fp32_predict(const float *f, float *conf) {
  float z[N_FEATURES], h[32], lg[N_CLASSES];
  for (int i = 0; i < N_FEATURES; i++) z[i] = (f[i] - M3_W64_R50_FP32_MEAN[i]) / M3_W64_R50_FP32_SCALE[i];
  for (int j = 0; j < 32; j++) {
    float s = M3_W64_R50_FP32_B1[j];
    for (int i = 0; i < N_FEATURES; i++) s += M3_W64_R50_FP32_W1T[j][i] * z[i];
    h[j] = s > 0.0f ? s : 0.0f;
  }
  int best = 0;
  for (int c = 0; c < N_CLASSES; c++) {
    float s = M3_W64_R50_FP32_B2[c];
    for (int j = 0; j < 32; j++) s += M3_W64_R50_FP32_W2T[c][j] * h[j];
    lg[c] = s;
    if (s > lg[best]) best = c;
  }
  float sum = 0.0f;
  for (int c = 0; c < N_CLASSES; c++) sum += expf(lg[c] - lg[best]);
  *conf = 1.0f / sum;
  return best;
}
